// A turn whose socket closed is abandoned rather than ended: nobody is left to read a terminal frame.
function endTurn(ws: WebSocket, session: ChatSession, signal: AbortSignal | undefined, startedAt: number): void {
  if (signal?.aborted) {
    log.info('message', 'turn abandoned: its socket closed', {
      sessionId: session.sessionId,
      elapsedMs: Date.now() - startedAt,
    });
    return;
  }
  sendStreamEnd(ws);
}

async function answerUserMessage(
  ws: WebSocket,
  session: ChatSession,
  orchestrator: ChatOrchestrator,
  sessionStore: SessionStore | undefined,
  validation: ValidationResult,
  signal: AbortSignal | undefined
): Promise<void> {
  const message = validation.valid ? validation.data : undefined;
  if (message?.type === 'user_message') return handleUserMessage(ws, session, orchestrator, message.content, signal);
  await answerFrame(ws, session, sessionStore, validation);
}

async function answerFrame(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  validation: ValidationResult
  ,options?: MessageHandlerOptions
): Promise<void> {
  if (!validation.valid) {
    log.warn('message', 'validation failed', {error: validation.error});
    sendError(ws, ErrorCodes.INVALID_MESSAGE, validation.error);
    return;
  }

  const message = validation.data;
  if (message.type === 'ping') handlePing(ws, message.timestamp);
  if (message.type === 'list_conversations') {
    if (!options?.history?.enabled || !sessionStore?.listFor) {
      sendError(ws, ErrorCodes.UNSUPPORTED, 'Conversation history is not enabled on this server');
      return;
    }
    const conversations = await sessionStore.listFor(session.userId, {
      limit: message.limit,
      before: message.before,
    });
    sendJson(ws, {type: 'conversation_list', conversations: conversations.map(toSessionSummaryFrame)});
    return;
  }
  if (message.type !== 'list_sessions') return;

  try {
    const sessions =
      (await sessionStore?.listFor?.(session.userId, {
        limit: message.limit,
        before: message.before,
      })) ?? [];
    sendJson(ws, {
      type: 'session_list',
      sessions: sessions.map(toSessionSummaryFrame),
    });
  } catch (error) {
    const detail = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'failed to list sessions', {userId: session.userId, error: detail});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to process message');
  }
}

function toSessionSummaryFrame(summary: {sessionId: string; createdAt: Date; updatedAt: Date; entryCount: number}): {
import type {IncomingMessage} from '../../types/messages.js';
import type {SessionCursor} from '../../types/sessionStore.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  switch (message.type) {
    case 'user_message':
      return validateUserMessage(message);
    case 'ping':
      return validatePingMessage(message);
    case 'list_sessions':
      return validateListSessionsMessage(message);
    case 'list_conversations':
      return validateListConversationsMessage(message);
    default:
      return {valid: false, error: `Unknown message type: ${message.type}`};
  }
}

function validateListConversationsMessage(message: Record<string, unknown>): ValidationResult {
  if (message.limit !== undefined && (!Number.isInteger(message.limit) || (message.limit as number) < 1 || (message.limit as number) > 200)) {
    return {valid: false, error: 'list_conversations limit must be an integer from 1 to 200'};
  }

  if (message.before !== undefined) {
    const before = message.before as Record<string, unknown>;
    if (
      typeof message.before !== 'object' ||
      message.before === null ||
      typeof before.sessionId !== 'string' ||
      before.sessionId.length < 1 ||
      before.sessionId.length > 128 ||
      typeof before.updatedAt !== 'string' ||
      Number.isNaN(Date.parse(before.updatedAt))
    ) {
      return {valid: false, error: 'list_conversations before must have a valid sessionId and updatedAt'};
    }
  }

  return {
    valid: true,
    data: {
      type: 'list_conversations',
      limit: message.limit as number | undefined,
